import numpy as np, collections
inp=np.array(list(map(int,"9 9 9 9 9 9 9 9 9 9 9;9 9 9 9 1 9 9 9 9 1 9;9 9 9 9 9 9 9 9 9 9 9;9 9 9 9 9 9 9 9 1 9 9;9 9 9 9 9 9 9 9 9 9 9;1 9 9 9 9 9 9 9 9 1 9;9 9 9 9 9 9 9 9 9 9 9;9 9 9 1 1 9 9 9 9 9 9;9 9 9 9 9 9 9 1 9 9 9;1 9 9 9 9 9 1 1 9 9 9".replace(';',' ').split()))).reshape(10,11)
out=np.array(list(map(int,"9 9 9 9 9 9 9 9 9 9 9;9 9 9 9 1 3 3 3 3 1 9;9 9 9 9 3 9 9 9 9 3 9;9 9 9 9 3 9 9 9 1 3 9;9 9 9 9 3 9 9 9 9 3 9;1 3 3 3 3 3 3 3 3 1 9;3 9 9 9 3 9 9 9 9 9 9;3 9 9 1 1 9 9 9 9 9 9;3 9 9 9 9 9 9 1 9 9 9;1 3 3 3 3 3 1 1 9 9 9".replace(';',' ').split()))).reshape(10,11)
# flood fill background from border
H,W=inp.shape
vis=np.zeros_like(inp,bool)
q=collections.deque()
for r in range(H):
    for c in range(W):
        if (r in(0,H-1) or c in(0,W-1)) and inp[r,c]==9:
            vis[r,c]=True;q.append((r,c))
while q:
    r,c=q.popleft()
    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<H and 0<=nc<W and not vis[nr,nc] and inp[nr,nc]==9:
            vis[nr,nc]=True;q.append((nr,nc))
pred=inp.copy()
pred[(inp==9)&~vis]=3
print(np.array_equal(pred,out))
